// The code below is a qualitative representation of the concept of exploitation in a hypothetical system.

// Define a class to represent a worker
class Worker {
    constructor(name, hoursWorked, wage) {
        this.name = name;
        this.hoursWorked = hoursWorked;
        this.wage = wage;
    }

    // Method to calculate total earnings
    calculateEarnings() {
        return this.hoursWorked * this.wage;
    }
}

// Define a class to represent a company
class Company {
    constructor(name) {
        this.name = name;
        this.workers = [];
    }

    // Method to add a worker to the company
    addWorker(worker) {
        this.workers.push(worker);
    }

    // Method to calculate total labor cost
    calculateTotalLaborCost() {
        return this.workers.reduce((total, worker) => total + worker.calculateEarnings(), 0);
    }

    // Method to simulate exploitation by reducing wages
    exploitWorkers() {
        this.workers.forEach(worker => {
            worker.wage *= 0.5; // Reduce wage by 50%
        });
    }
}

// Example usage
const company = new Company(Exploitation Inc.);
const worker1 = new Worker(Alice, 40, 15);
const worker2 = new Worker(Bob, 40, 15);

company.addWorker(worker1);
company.addWorker(worker2);

console.log(Total labor cost before exploitation:, company.calculateTotalLaborCost());

company.exploitWorkers();

console.log(Total labor cost after exploitation:, company.calculateTotalLaborCost());
```

